export type Tag = { icon: string; label: string; warn?: boolean };

export type Exercise = { id: string; group: AgeGroup; text: string };

export type Place = {
  id: string;
  name: string;
  address: string;
  lat: number;
  lng: number;
  /** null = fee unknown */
  free: boolean | null;
  surfaces: SurfaceId[];
  facilities: FacilityId[];
  tags: Tag[];
  exercises: Exercise[];
  source?: "curated" | "osm";
  kind?: string;
  ward?: string | null;
  named?: boolean;
  osm?: string;
};

