const fold = (s: string) => s.toLowerCase().normalize("NFD").replace(/[̀-ͯ]/g, "").replace(/đ/g, "d");
const nearM = (a: Place, b: Place) =>
  Math.hypot((a.lat - b.lat) * 111320, (a.lng - b.lng) * 111320 * Math.cos((a.lat * Math.PI) / 180));

// an OSM entry duplicating a curated place (same name, < 500 m apart) is dropped
const curatedKeys = curatedPlaces.map((c) => ({ c, key: fold(c.name) }));
const osm = (osmPlaces as Place[]).filter(
  (o) => !(o.named && curatedKeys.some(({ c, key }) => nearM(c, o) < 500 && (key.includes(fold(o.name)) || fold(o.name).includes(key)))),
);

export const places: Place[] = [...curatedPlaces.map((p) => ({ ...p, source: "curated" as const, named: true })), ...osm];

export const exerciseById = new Map(places.flatMap((p) => p.exercises.map((e) => [e.id, { ...e, place: p.name }] as const)));
